import pandas as pd
import numpy as np

# Load the data
transport_data = pd.read_csv('getisord_2021_transport.csv')
adjacency_data = pd.read_csv('borough_adjacency.csv')

# Check for missing values
if transport_data['Transport_value'].isnull().sum() > 0:
    print("Error: Missing values in Transport_value column")
    exit()

# Create a dictionary to store the neighboring boroughs for each borough
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Create a dictionary to store the combined Transport values for each borough
combined_transport = {}
for index, row in transport_data.iterrows():
    if row['borough'] not in combined_transport:
        combined_transport[row['borough']] = row['Transport_value']
    for neighbor in neighborhoods[row['borough']]:
        if neighbor in combined_transport:
            combined_transport[row['borough']] += transport_data.loc[transport_data['borough'] == neighbor, 'Transport_value'].values[0]

# Calculate the citywide average of the combined Transport values
citywide_average = np.mean(list(combined_transport.values()))

# Calculate the standard deviation of the combined Transport values
std_dev = np.std(list(combined_transport.values()))

# Calculate the z-scores for each borough
z_scores = {}
for borough, transport_value in combined_transport.items():
    z_score = (transport_value - citywide_average) / std_dev
    z_scores[borough] = z_score

# Identify the boroughs that are statistically significant hot or cold spots
hot_cold_spots = {}
for borough, z_score in z_scores.items():
    if np.abs(z_score) > 1.96:
        hot_cold_spots[borough] = z_score

# Print the results
data_points_used = len(hot_cold_spots)
print(f"data_points_used = {data_points_used}")

# Print the final answer
if hot_cold_spots:
    results = [f"{borough} (HOT, Gi*={z_score:.4f}, gi_value={z_score:.4f})" for borough, z_score in hot_cold_spots.items()]
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")
